using System;using System.IO;using System.Linq;using System.Security.Cryptography;using System.Text;using IdleIntelligence.Core;using IdleIntelligence.Runtime;using NUnit.Framework;
namespace IdleIntelligence.Tests {
 public sealed class MetaCatalogMigrationTests {
  static string Hash(string value){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(Encoding.UTF8.GetBytes(value))).Replace("-","").ToLowerInvariant();}
  static void Legacy(WorkshopState w){w.learned=w.learned.Take(30).ToArray();w.knownBlueprints=w.knownBlueprints.Take(30).ToArray();w.mastery=w.mastery.Take(30).ToArray();w.crafted=w.crafted.Take(30).ToArray();}
  [Test]public void Version22CatalogPreservesItemsIndicesAndOriginalOnAtomicUpgrade(){string dir=Path.Combine(Path.GetTempPath(),"meta-catalog-"+Guid.NewGuid());Directory.CreateDirectory(dir);try{var s=Game.New(1000);s.Workshop.learned[29]=true;s.Workshop.knownBlueprints[29]=true;s.Workshop.mastery[29]=2;s.Workshop.crafted[29]=7;s.Workshop.fragments=83;var dto=StateData.From(s);Legacy(dto.workshop);var codec=new UnitySaveCodec();string payload=codec.Encode(dto);string raw=codec.EncodeEnvelope(new SaveEnvelope{format=AtomicSaveStore.Format,version=22,payload=payload,sha256=Hash(payload)});string path=Path.Combine(dir,"save.json");File.WriteAllText(path,raw);var store=new AtomicSaveStore(path,codec);var loaded=store.Load(1000);Assert.That(loaded.Writable,Is.True,loaded.Message);var w=loaded.State.Workshop;Assert.That(w.learned.Length,Is.EqualTo(36));Assert.That(w.learned[29],Is.True);Assert.That(w.mastery[29],Is.EqualTo(2));Assert.That(w.crafted[29],Is.EqualTo(7));Assert.That(w.fragments,Is.EqualTo(83));Assert.That(w.learned.Skip(30).Any(x=>x),Is.False);Assert.That(w.mastery.Skip(30).Sum(),Is.Zero);Assert.That(File.ReadAllText(Directory.GetFiles(dir,"*.v22-original-*").Single()),Is.EqualTo(raw));store.Save(loaded.State);Assert.That(codec.DecodeEnvelope(File.ReadAllText(path)).version,Is.EqualTo(23));Assert.That(File.ReadAllText(path+".backup"),Is.EqualTo(raw));Assert.That(store.Load(1000).State.Workshop.crafted[29],Is.EqualTo(7));}finally{Directory.Delete(dir,true);}}
  [Test]public void Version22ChallengeAndSuspendedMainBothExpandWithoutLosingPermanentEvidence(){var codec=new UnitySaveCodec();var dto=StateData.From(Game.New(1000));dto.hasChallenge=true;dto.challengeMain=StateData.From(Game.New(1000));dto.workshop.crafted[29]=4;dto.challengeMain.workshop.crafted[29]=9;Legacy(dto.workshop);Legacy(dto.challengeMain.workshop);var result=codec.Decode(codec.Encode(dto),22);Assert.That(result.workshop.crafted.Length,Is.EqualTo(36));Assert.That(result.challengeMain.workshop.crafted.Length,Is.EqualTo(36));Assert.That(result.workshop.crafted[29],Is.EqualTo(4));Assert.That(result.challengeMain.workshop.crafted[29],Is.EqualTo(9));Assert.That(result.challengeMain.workshop.crafted.Skip(30).Sum(),Is.Zero);}
  [Test]public void UnknownLegacyCatalogIsRejectedRatherThanTruncated(){var codec=new UnitySaveCodec();var dto=StateData.From(Game.New(1000));dto.workshop.mastery=new int[37];Assert.Throws<FormatException>(()=>codec.Decode(codec.Encode(dto),22));dto=StateData.From(Game.New(1000));dto.workshop.learned=new bool[29];Assert.Throws<FormatException>(()=>codec.Decode(codec.Encode(dto),22));}
 }
}
